let currentIndex = 0;
const track = document.getElementById('sliderTrack');
const totalCards = document.querySelectorAll('.slider-track .card').length;
const visibleCards = 4;
const cardWidth = document.querySelector('.slider-track .card').offsetWidth + 24; // + gap
const maxIndex = totalCards - visibleCards;

function slideTestimonials(direction) {
  currentIndex += direction;
  
  if (currentIndex < 0) {
    currentIndex = maxIndex - 1;
    track.style.transition = 'none';
    track.style.transform = `translateX(-${currentIndex * cardWidth}px)`;
    setTimeout(() => {
      track.style.transition = 'transform 0.5s ease';
      currentIndex = maxIndex - 2;
      track.style.transform = `translateX(-${currentIndex * cardWidth}px)`;
    }, 10);
    return;
  }
  
  if (currentIndex >= maxIndex) {
    currentIndex = 1;
    track.style.transition = 'none';
    track.style.transform = `translateX(-${currentIndex * cardWidth}px)`;
    setTimeout(() => {
      track.style.transition = 'transform 0.5s ease';
      currentIndex = 0;
      track.style.transform = `translateX(0)`;
    }, 10);
    return;
  }
  
  track.style.transform = `translateX(-${currentIndex * cardWidth}px)`;
}

// Auto-slide every 5 seconds
let autoSlide = setInterval(() => slideTestimonials(1), 5000);

// Pause on hover
document.querySelector('.testimonial-slider').addEventListener('mouseenter', () => {
  clearInterval(autoSlide);
});

document.querySelector('.testimonial-slider').addEventListener('mouseleave', () => {
  autoSlide = setInterval(() => slideTestimonials(1), 5000);
});

// Update card width on resize
window.addEventListener('resize', () => {
  const newCardWidth = document.querySelector('.slider-track .card').offsetWidth + 24;
  // Recalculate and reset
  track.style.transition = 'none';
  track.style.transform = `translateX(-${currentIndex * newCardWidth}px)`;
  setTimeout(() => {
    track.style.transition = 'transform 0.5s ease';
  }, 10);
});